services:
  web:
    environment:
      WORDPRESS_CONFIG_EXTRA: 'if (!defined(''WP_DEBUG'')) { define(''WP_DEBUG'',
        false); }

        define(''DISALLOW_FILE_EDIT'', true);

        // The Defender terminates TLS and forwards the client address.

        if (isset($$_SERVER[''HTTP_X_FORWARDED_PROTO'']) && $$_SERVER[''HTTP_X_FORWARDED_PROTO'']
        === ''https'') { $$_SERVER[''HTTPS''] = ''on''; }


        if (isset($$_SERVER[''HTTP_HOST'']) && in_array($$_SERVER[''HTTP_HOST''],
        [''192.168.56.10'', ''10.10.10.3:8080''], true)) { define(''WP_HOME'', (isset($$_SERVER[''HTTPS''])
        && $$_SERVER[''HTTPS''] === ''on'' ? ''https'' : ''http'') . ''://'' . $$_SERVER[''HTTP_HOST'']);
        define(''WP_SITEURL'', WP_HOME); }

        '
    volumes:
    - ./trap-access.conf:/etc/apache2/conf-enabled/trap-access.conf:ro
LogFormat "client=%{X-Forwarded-For}i peer=%a timestamp=%{%Y-%m-%dT%H:%M:%S%z}t request=\"%r\" status=%>s" trap_origin
GlobalLog /proc/self/fd/1 trap_origin
